import { getNodesValueSum } from './get-nodes-value-sum.js';
import type { ColorToken } from '../../core/types/color-palette.js';
import { DEFAULT_AGGREGATED_LABEL } from '../constants.js';
import { InternalTreeMapLeafNode } from '../types/internal.js';

export const getAggregatedNode = (
  nodes: InternalTreeMapLeafNode[],
  rootNodeColor: ColorToken | undefined,
) => {
  const aggregatedNode = {
    value: getNodesValueSum(nodes),
    name: DEFAULT_AGGREGATED_LABEL,
    color: rootNodeColor,
  };

  return aggregatedNode;
};
